    @Test void optionalMachineMixinsTargetNativeCompletionBoundaries()throws Exception{String ae2=Files.readString(Path.of("src/main/java/com/bettercontent/threads/mixin/Ae2CraftingCpuMixin.java"));assertTrue(ae2.contains("method = \"done\""));String occult=Files.readString(Path.of("src/main/java/com/bettercontent/threads/mixin/OccultismRitualBowlMixin.java"));assertTrue(occult.contains("method = \"startRitual\""));assertTrue(occult.contains("method = \"stopRitual\""));String source=Files.readString(Path.of("src/main/java/com/bettercontent/threads/mixin/ArsSourceEnergyMixin.java"));assertTrue(source.contains("method = \"addSource\""));}
