    @Test void authoredArsSpellsCompleteOnlyOnMatchingNativeEffect()throws Exception{String source=Files.readString(Path.of("src/main/java/com/bettercontent/threads/compat/ArsNouveauThreads.java"));assertTrue(source.contains("EffectResolveEvent.Post"));assertTrue(source.contains("signature.equals(state.getString"));assertTrue(source.contains("token.equals(active)"));String mixin=Files.readString(Path.of("src/main/java/com/bettercontent/threads/mixin/ArsUpdateCasterMixin.java"));assertTrue(mixin.contains("PacketUpdateCaster"));assertTrue(mixin.contains("spellRecipe.clone()"));}
